cat > spec/list_date.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
BOOKINGS=$t bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "month 13 should exit 2"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-32 >/dev/null 2>&1; [ $? = 2 ] || { echo "day 32 should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "a well-formed date should list its bookings"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check; echo "check rc=$?"; bash tools/lint; echo "lint rc=$?"

